        tx, ty = min(resources, key=lambda p: (dist(sx, sy, p[0], p[1]), p[0], p[1]))
    else:
        tx, ty = (w - 1) // 2, (h - 1) // 2

    best = None
    best_key = None
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not inb(nx, ny) or (nx, ny) in obstacles:
            continue
        key = (dist(nx, ny, tx, ty), dx != 0 or dy != 0, dx, dy)
        if best_key is None or key < best_key:
            best_key = key
            best = (dx, dy)

    if best is None:
        return [0, 0]
    return [int(best[0]), int(best[1])]

